import json
import re
from docx import Document

def replace_in_para(para, data):
    text = para.text
    pattern = r'\{\{([A-Z_]+)\}\}'
    if not re.search(pattern, text):
        return False

    new_text = text
    found = False
    for match in re.finditer(pattern, text):
        key = match.group(1)
        placeholder = match.group(0)
        if key in data:
            new_text = new_text.replace(placeholder, str(data[key]))
            found = True

    if found:
        if para.runs:
            # Preserve formatting of the first run if possible
            para.runs[0].text = new_text
            for run in para.runs[1:]:
                run.text = ''
        else:
            para.text = new_text
    return found

def fill_template():
    with open('employee_data.json', 'r') as f:
        data = json.load(f)

    doc = Document('offer_letter_template.docx')

    # 1. Handle Relocation Conditional
    # The prompt says: keep if RELOCATION_PACKAGE is "Yes"
    should_keep = data.get("RELOCATION_PACKAGE") == "Yes"

    start_marker = "{{IF_RELOCATION}}"
    end_marker = "{{END_IF_RELOCATION}}"

    # We need to be careful with iterating while deleting
    # First, find the indices
    paragraphs = list(doc.paragraphs)
    start_idx = -1
    end_idx = -1

    for i, p in enumerate(paragraphs):
        if start_marker in p.text:
            start_idx = i
        if end_marker in p.text:
            end_idx = i

    if start_idx != -1 and end_idx != -1:
        if should_keep:
            # Keep content, remove markers from the text
            p_start = doc.paragraphs[start_idx]
            p_start.text = p_start.text.replace(start_marker, "")
            # Clean up if it was just the marker
            if not p_start.text.strip():
                p_start.text = ""

            p_end = doc.paragraphs[end_idx]
            p_end.text = p_end.text.replace(end_marker, "")
            if not p_end.text.strip():
                p_end.text = ""
        else:
            # Remove all paragraphs from start_idx to end_idx inclusive
            # Collect elements to remove
            to_remove = []
            for i in range(start_idx, end_idx + 1):
                to_remove.append(doc.paragraphs[i]._element)

            for el in to_remove:
                el.getparent().remove(el)

    # 2. Global replacement for all remaining paragraphs
    for para in doc.paragraphs:
        replace_in_para(para, data)

    # 3. Tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_para(para, data)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # 4. Headers/Footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            replace_in_para(para, data)
        for para in section.footer.paragraphs:
            replace_in_para(para, data)

    doc.save('offer_letter_filled.docx')

if __name__ == "__main__":
    fill_template()

